function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0;
    var v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

// Coerce a JSON-string into an object/array. Returns null on empty/parse-fail (fail-soft).
function parseJsonField(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'object') return v;
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch (e) { return null; }
  }
  return null;
}

// Normalize response to canonical {status_code, body, error}. Accepts old {status, data} too.
function normalizeResponse(r) {
  if (!r || typeof r !== 'object') return null;
  var sc = null;
  var srcSc = r.status_code !== undefined ? r.status_code
            : r.statusCode  !== undefined ? r.statusCode
            : r.status       !== undefined ? r.status
            : null;
  if (srcSc !== null && srcSc !== '') {
    var n = typeof srcSc === 'number' ? srcSc : Number(srcSc);
    sc = isNaN(n) ? null : n;
  }
  var body = r.body !== undefined ? r.body : (r.data !== undefined ? r.data : null);
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { /* leave as string */ }
  }
  var error = (r.error === undefined || r.error === '') ? null : r.error;
  return { status_code: sc, body: body, error: error };
}

var params = startTrigger.params;

var payloadObj = parseJsonField(params.payload);
var requestObj = parseJsonField(params.request);
var responseObj = normalizeResponse(parseJsonField(params.response));

var rollbackOfVersion = null;
if (params.rollback_of_version !== undefined && params.rollback_of_version !== null && params.rollback_of_version !== '') {
  var rv = Number(params.rollback_of_version);
  rollbackOfVersion = isNaN(rv) ? null : rv;
}

var data = {
  // ---- canonical identifiers ----
  event_type: params.event_type,
  workspace_name: params.workspace_name,
  app_name: params.app_name,
  page_name: params.page_name,
  config_type: params.config_type,
  config_group_id: params.config_group_id,
  current_version: Number(params.current_version) || 0,
  actor_email: params.actor_email,
  actor_role: params.actor_role,
  user_email: params.user_email,

  // ---- LLD V2 / canonical audit row ----
  config_version_id: params.config_version_id || '',
  intent: params.intent || '',
  is_rollback: params.is_rollback === true || params.is_rollback === 'true',
  rollback_of_version: rollbackOfVersion,
  rollback_target_id: params.rollback_target_id || null,
  rollback_from_id: params.rollback_from_id || null,
  outcome: params.outcome || null,
  effective_from: params.effective_from || null,
  effective_to: params.effective_to || null,
  country_code: params.country_code || '',
  geo_region_id: Number(params.geo_region_id) || null,
  vehicle_category: params.vehicle_category || '',
  change_request_id: params.change_request_id || '',

  metadata: {
    trace_id: generateUUID(),
    event_id: generateUUID(),
    event_published_at: new Date().toISOString()
  }
};

if (params.comment) data.comment = params.comment;
if (params.created_at) data.created_at = params.created_at;
if (payloadObj !== null) data.payload = payloadObj;
if (requestObj !== null) data.request = requestObj;
if (responseObj !== null) data.response = responseObj;

return {
  value: {
    type: 'JSON',
    data: data
  }
};
